CREATE DATABASE IF NOT EXISTS hj_earnings CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE hj_earnings;
CREATE TABLE users(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,email VARCHAR(190) UNIQUE NOT NULL,password_hash VARCHAR(255) NOT NULL,role ENUM('user','admin') DEFAULT 'user',referral_code VARCHAR(32) UNIQUE NOT NULL,referred_by BIGINT UNSIGNED NULL,points BIGINT NOT NULL DEFAULT 0,total_earned_points BIGINT NOT NULL DEFAULT 0,spins INT NOT NULL DEFAULT 0,referrals INT NOT NULL DEFAULT 0,last_bonus_date DATE NULL,last_bonus_claimed_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(referred_by) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE transactions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,type ENUM('bonus','spin','referral','withdrawal','adjustment') NOT NULL,points BIGINT NOT NULL,description VARCHAR(255) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(user_id,created_at),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE withdrawals(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,points BIGINT NOT NULL,rupees DECIMAL(12,2) NOT NULL,method ENUM('Easypaisa','JazzCash') NOT NULL,account_number VARCHAR(100) NOT NULL,status ENUM('Pending','Complete','Rejected') DEFAULT 'Pending',admin_note VARCHAR(500),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX(status,created_at),INDEX(user_id,created_at),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);

CREATE TABLE IF NOT EXISTS redeem_codes(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,code VARCHAR(64) UNIQUE NOT NULL,points BIGINT NOT NULL,max_uses INT NOT NULL DEFAULT 1,used_count INT NOT NULL DEFAULT 0,expires_at DATETIME NULL,active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS redeem_code_uses(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,code_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY(code_id,user_id),FOREIGN KEY(code_id) REFERENCES redeem_codes(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
